    public virtual void handleTicker(WebSocketClient client, object message)
    {
        //
        //     {
        //         "server_id": "q0",
        //         "conidEx": "495759171",
        //         "conid": 495759171,
        //         "_updated": 1702334859712,
        //         "6119": "q0",
        //         "31": "2428.50",
        //         "84": "2428.25",
        //         "86": "2428.75",
        //         "topic": "smd+495759171"
        //     }
        //
        string? topic = this.safeString(message, "topic", "");
        List<object> parts = topic.Split(new [] {"+"}, StringSplitOptions.None).ToList<object>();
        string? marketId = this.safeString(parts, 1);
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        // the updates are deltas (only the changed fields are sent), they are merged into the previous raw ticker,
        // the bidsasks cache is the fallback in case the tickers cache was cleaned by unWatchTickers
        IDictionary<string, object> previous = this.safeDict(this.tickers, symbol);
        if ((previous == null))
        {
            previous = this.safeDict(this.bidsasks, symbol, new Dictionary<string, object>() {});
        }
        IDictionary<string, object> previousInfo = this.safeDict(previous, "info", new Dictionary<string, object>() {});
        Dictionary<string, object> merged = this.extend(previousInfo, message);
        if ((this.safeInteger(message, "_updated") == null))
        {
            merged["_updated"] = this.milliseconds();
        }
        ccxt.Ticker ticker = this.parseTicker(merged, market);
        this.tickers[(string)symbol] = ccxt.BaseExchange.FromTicker(ticker);
        client.resolve(ccxt.BaseExchange.FromTicker(ticker), ("ticker::" + symbol));
        // a delta without bid/ask fields (e.g. only the mark price 7635) does not change the best bid and ask,
        // and nothing is emitted to watchBidsAsks until a bid or an ask has been received
        bool hasBidAsk = ((message != null && ((IDictionary<string, object>)message).ContainsKey("84"))) || ((message != null && ((IDictionary<string, object>)message).ContainsKey("85"))) || ((message != null && ((IDictionary<string, object>)message).ContainsKey("86"))) || ((message != null && ((IDictionary<string, object>)message).ContainsKey("88")));
        bool hasQuote = (!((((object)ticker.bid)) == null)) || (!((((object)ticker.ask)) == null));
        if (hasBidAsk && hasQuote)
        {
            ccxt.Ticker bidAsk = this.safeTicker(new Dictionary<string, object>() {
                { "symbol", symbol },
                { "timestamp", (((object)ticker.timestamp)) },
                { "datetime", (((object)ticker.datetime)) },
                { "bid", this.safeString(ccxt.BaseExchange.FromTicker(ticker), "bid") },
                { "bidVolume", this.safeString(ccxt.BaseExchange.FromTicker(ticker), "bidVolume") },
                { "ask", this.safeString(ccxt.BaseExchange.FromTicker(ticker), "ask") },
                { "askVolume", this.safeString(ccxt.BaseExchange.FromTicker(ticker), "askVolume") },
                { "info", merged },
            }, market);
            this.bidsasks[(string)symbol] = ccxt.BaseExchange.FromTicker(bidAsk);
            client.resolve(ccxt.BaseExchange.FromTicker(bidAsk), ("bidask::" + symbol));
        }
        this.ibkrUpdateOHLCVs(client, symbol, message);
    }

