                Int64 now = this.milliseconds();
                Int64? firstFilled = this.safeInteger(subscription, "firstFilled", now);
                subscription["firstFilled"] = firstFilled;
                ((IDictionary<string,object>)client.subscriptions)[messageHash] = subscription;
                Int64? skipTimeout = this.safeInteger(options, "skipFirstItemTimeout", 10000);
                if ((((now - firstFilled)) < skipTimeout))
                {
                    return;
                }
            }
        }
        subscription["emitted"] = true;
        ((IDictionary<string,object>)client.subscriptions)[messageHash] = subscription;
        Int64 timestamp = this.milliseconds();
        ccxt.OrderBook snapshot = this.parseOrderBook(new Dictionary<string, object>() {
            { "bids", bids },
            { "asks", asks },
        }, symbol, timestamp);
        ccxt.pro.IOrderBook orderbook = this.safeOrderBook(this.orderbooks, symbol);
        if ((orderbook == null))
        {
            orderbook = this.orderBook(new Dictionary<string, object>() {});
            ((IDictionary<string,object>)this.orderbooks)[(string)symbol] = orderbook;
        }
        (orderbook as IOrderBook).reset(ccxt.BaseExchange.FromOrderBook(snapshot));
        client.resolve(orderbook, messageHash);
    }

    /**
     * @method
     * @name interactivebrokers#watchOrders
     * @description watches information on multiple orders made by the user
     * @see https://www.interactivebrokers.com/docs/web-api/ws/order-updates
     * @param {string} [symbol] unified market symbol of the market the orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string[]} [params.filters] order status filters, e.g. [ 'Submitted', 'Filled' ]
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-live-orders
     */
    public async override Task<List<ccxt.Order>> WatchOrders(string symbol = null, Int64? since = null, Int64? limit = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        string messageHash = "orders";
        string? unifiedSymbol = null;
        if ((symbol != null))
        {
            IDictionary<string, object> watchOrdersOptions = this.safeDict(this.options, "watchOrders", new Dictionary<string, object>() {});
            bool? warnIfWithoutSymbol = this.safeBool(watchOrdersOptions, "warnIfWithoutSymbol", true);
            if ((warnIfWithoutSymbol == true))
            {
                throw new ExchangeError ((this.id + " watchOrders() with a symbol argument can miss order updates: the orders from previous sessions are not fetched, and the sor updates of the orders not created on this connection carry only the orderId and the status (no conid), so they can not be matched to a symbol. It is recommended to call watchOrders() without the symbol argument and filter the results by symbol. To proceed with the symbol argument anyway and acknowledge this, set exchange.options[\"watchOrders\"][\"warnIfWithoutSymbol\"] = false")) ;
            }
            unifiedSymbol = this.symbol(symbol);
            messageHash = ((messageHash + "::") + unifiedSymbol);
        }
        object url = await this.ibkrConnect();
        var client = this.client(url);
        // the sor updates of the orders that were not created on this connection carry only the orderId and the status,
        // the full raw orders are seeded from the rest snapshot, the updates are merged into them by orderId
        Dictionary<string, object> rawOrders = new Dictionary<string, object>() {};
        if (!((client.subscriptions != null && client.subscriptions.ContainsKey("sor"))))
        {
            IDictionary<string, object> options = this.safeDict(this.options, "watchOrders", new Dictionary<string, object>() {});
            bool? fetchOrdersSnapshot = this.safeBool(options, "fetchOrdersSnapshot", true);
            if ((fetchOrdersSnapshot == true))
            {
                object snapshot = await this.fetchLiveOrdersRaw();
                for (int i = 0; i < getArrayLength(snapshot); i++)
                {
                    IDictionary<string, object> rawOrder = ((IDictionary<string, object>)getValue(snapshot, i));
                    string? orderId = this.safeString(rawOrder, "orderId");
                    if ((orderId != null))
                    {
                        rawOrders[(string)orderId] = rawOrder;
                    }
                }
            }
        }
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        var future = client.reusableFuture(messageHash);
        List<object> filters = this.safeList(parameters, "filters");
        // an empty dict is json-encoded as [] in php, so the empty arguments are sent as a literal
        string requestArgs = "{}";
        if ((filters != null))
        {
            Dictionary<string, object> requestParams = new Dictionary<string, object>() {
                { "filters", filters },
            };
            requestArgs = this.json(requestParams);
        }
        await this.ibkrSubscribe(client, "sor", ("sor+" + requestArgs), new Dictionary<string, object>() {
            { "rawOrders", rawOrders },
        });
        object orders = await future;
        Int64? resultLimit = limit;
        if (this.newUpdates)
        {
            resultLimit = ((Int64?)ccxt.pro.BaseCache.getLimitOf(orders, unifiedSymbol, limit));
        }
        return ccxt.BaseExchange.ToOrderList(this.filterBySymbolSinceLimit(this.toArray(orders), unifiedSymbol, since, resultLimit, true));
    }

    /**
     * @method
     * @name interactivebrokers#unWatchOrders
     * @description unWatches information on multiple orders made by the user
     * @see https://www.interactivebrokers.com/docs/web-api/ws/order-updates
     * @param {string} [symbol] not used by interactivebrokers.unWatchOrders, all the order streams are cancelled
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {boolean} true
     */
    public async override Task<object> unWatchOrders(string? symbol = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object url = await this.ibkrConnect();
        var client = this.client(url);
        this.cleanUnsubscription(client, "orders", "unsubscribe::orders", true);
        string emptyArgs = "{}"; // a separate literal, the php transpiler turns '+{}' into '+array()'
        return await this.ibkrUnsubscribe(client, new List<object>() {"sor"}, ("uor+" + emptyArgs), new Dictionary<string, object>() {
            { "topic", "orders" },
        });
    }

    public virtual void handleOrders(WebSocketClient client, object message)
    {
        //
        //     {
        //         "topic": "sor",
        //         "args": [
        //             {
        //                 "acct": "U1234567",
        //                 "conid": 265598,
        //                 "orderId": 1234568790,
        //                 "orderType": "Limit",
        //                 "side": "BUY",
        //                 "price": "185.50",
        //                 "status": "Submitted",
        //                 "filledQuantity": 0.0,
        //                 "remainingQuantity": 5.0,
        //                 "totalSize": 5.0,
        //                 "timeInForce": "CLOSE",
        //                 "lastExecutionTime_r": 1702317649000,
        //                 "order_ref": "my-id"
        //             }
        //         ]
        //     }
        //
        List<object> args = this.safeList(message, "args", new List<object>() {});
        int argsLength = args.Count;
        if ((argsLength == 0))
        {
            return;
        }
        if ((this.orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache orders = this.orders;
        // the updates are partial, e.g. { "acct": "U1234567", "orderId": 1911471157, "status": "Cancelled" } without the conid,
        // they are merged into the previous raw order of the same orderId
        IDictionary<string, object> subscription = this.safeDict(client.subscriptions, "sor");
        IDictionary<string, object> rawOrders = this.safeDict(subscription, "rawOrders", new Dictionary<string, object>() {});
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        for (int i = 0; i < args.Count; i++)
        {
            object rawOrder = args[i];
            string? orderId = this.safeString(rawOrder, "orderId");
            object merged = rawOrder;
            if ((orderId != null))
            {
                IDictionary<string, object> previous = this.safeDict(rawOrders, orderId, new Dictionary<string, object>() {});
                merged = this.extend(previous, rawOrder);
                rawOrders[(string)orderId] = merged;
            }
            ccxt.Order parsed = this.parseOrder(merged);
            orders.append(ccxt.BaseExchange.FromOrder(parsed));
            string? orderSymbol = parsed.symbol;
            if ((orderSymbol != null))
            {
                symbols[(string)orderSymbol] = true;
            }
        }
        if ((subscription != null))
        {
            subscription["rawOrders"] = rawOrders;
            ((IDictionary<string,object>)client.subscriptions)["sor"] = subscription;
        }
        client.resolve(orders, "orders");
        List<object> keys = new List<object>(symbols.Keys);
        for (int i = 0; i < keys.Count; i++)
        {
            client.resolve(orders, ("orders::" + (keys[i])));
        }
    }

    /**
     * @method
     * @name interactivebrokers#watchMyTrades
     * @description watches information on multiple trades made by the user
     * @see https://www.interactivebrokers.com/docs/web-api/ws/trades
     * @param {string} [symbol] unified market symbol of the market the trades were made in
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trade structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.realtimeUpdatesOnly] return only the executions made after subscribing, default true, false also returns the executions of the last params.days days, the filtering is done client-side
     * @param {int} [params.days] number of days of past executions requested on subscribing, default 1
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    public async override Task<List<ccxt.Trade>> WatchMyTrades(string symbol = null, Int64? since = null, Int64? limit = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        string messageHash = "myTrades";
        string? unifiedSymbol = null;
        if ((symbol != null))
        {
            unifiedSymbol = this.symbol(symbol);
            messageHash = ((messageHash + "::") + unifiedSymbol);
        }
        object url = await this.ibkrConnect();
        var client = this.client(url);
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        var future = client.reusableFuture(messageHash);
        IDictionary<string, object> options = this.safeDict(this.options, "watchMyTrades", new Dictionary<string, object>() {});
        bool? realtimeUpdatesOnly = this.safeBool(parameters, "realtimeUpdatesOnly", this.safeBool(options, "realtimeUpdatesOnly", true));
        // the server handles realtimeUpdatesOnly=true unreliably, sometimes it replays the executions of the last days anyway,
        // sometimes it sends no executions at all (not even the new ones), so the stream is always requested with
        // realtimeUpdatesOnly=false and the executions older than the subscription are dropped on the client side instead
        Dictionary<string, object> requestParams = new Dictionary<string, object>() {
            { "realtimeUpdatesOnly", false },
            { "days", this.safeInteger(parameters, "days", this.safeInteger(options, "days", 1)) },
        };
        Dictionary<string, object> subscription = new Dictionary<string, object>() {
            { "realtimeUpdatesOnly", realtimeUpdatesOnly },
            { "subscribedAt", this.milliseconds() },
        };
        await this.ibkrSubscribe(client, "str", ("str+" + this.json(requestParams)), subscription);
        object trades = await future;
        Int64? resultLimit = limit;
        if (this.newUpdates)
        {
            resultLimit = ((Int64?)ccxt.pro.BaseCache.getLimitOf(trades, unifiedSymbol, limit));
        }
        return ccxt.BaseExchange.ToTradeList(this.filterBySymbolSinceLimit(this.toArray(trades), unifiedSymbol, since, resultLimit, true));
    }

    /**
     * @method
     * @name interactivebrokers#unWatchMyTrades
     * @description unWatches information on multiple trades made by the user
     * @see https://www.interactivebrokers.com/docs/web-api/ws/trades
     * @param {string} [symbol] not used by interactivebrokers.unWatchMyTrades, all the trade streams are cancelled
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {boolean} true
     */
    public async override Task<object> unWatchMyTrades(string? symbol = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object url = await this.ibkrConnect();
        var client = this.client(url);
        this.cleanUnsubscription(client, "myTrades", "unsubscribe::myTrades", true);
        return await this.ibkrUnsubscribe(client, new List<object>() {"str"}, "utr", new Dictionary<string, object>() {
            { "topic", "myTrades" },
        });
    }

    public virtual void handleMyTrades(WebSocketClient client, object message)
    {
        //
        //     {
        //         "topic": "str",
        //         "args": [
        //             {
        //                 "execution_id": "0000e0d5.6576fd38.01.01",
        //                 "symbol": "AAPL",
        //                 "side": "B",
        //                 "order_description": "Bot 5 @ 192.26 on ISLAND",
        //                 "trade_time_r": 1702319146000,
        //                 "size": 5,
        //                 "price": "192.26",
        //                 "order_ref": "my-id",
        //                 "exchange": "ISLAND",
        //                 "net_amount": 961.3,
        //                 "account": "U1234567",
        //                 "conid": 265598
        //             }
        //         ]
        //     }
        //
        List<object> args = this.safeList(message, "args", new List<object>() {});
        int argsLength = args.Count;
        if ((argsLength == 0))
        {
            return;
        }
        if ((this.myTrades == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            this.myTrades = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache trades = this.myTrades;
        // with realtimeUpdatesOnly the past executions replayed by the server are dropped, trade_time_r has a second precision
        IDictionary<string, object> subscription = this.safeDict(client.subscriptions, "str", new Dictionary<string, object>() {});
        bool? realtimeUpdatesOnly = this.safeBool(subscription, "realtimeUpdatesOnly", false);
        Int64? threshold = null;
        if ((realtimeUpdatesOnly == true))
        {
            Int64? subscribedAt = this.safeInteger(subscription, "subscribedAt");
            if ((subscribedAt != null))
            {
                threshold = (this.parseToInt(((double?)subscribedAt / 1000)) * 1000);
            }
        }
        // the same execution can be sent several times, first without the commission, then with it, then again unchanged,
        // an execution identical to the cached one with the same id is not emitted again
        IDictionary<string, object> options = this.safeDict(this.options, "watchMyTrades", new Dictionary<string, object>() {});
        bool? skipDuplicates = this.safeBool(options, "skipDuplicates", true);
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        for (int i = 0; i < args.Count; i++)
        {
            object rawTrade = args[i];
            ccxt.Trade trade = this.parseTrade(rawTrade);
            object tradeTimestamp = (((object)trade.timestamp));
            if (((threshold != null)) && (!(tradeTimestamp == null)) && (isLessThan(tradeTimestamp, threshold)))
            {
                continue;
            }
            if ((skipDuplicates == true))
            {
                IDictionary<string, object> cachedBySymbol = this.safeDict((trades as ArrayCache).hashmap, (((object)trade.symbol)), new Dictionary<string, object>() {});
                IDictionary<string, object> cached = this.safeDict(cachedBySymbol, (((object)trade.id)));
                if ((cached != null))
                {
                    IDictionary<string, object> cachedInfo = this.safeDict(cached, "info", new Dictionary<string, object>() {});
                    if ((this.json(cachedInfo) == this.json(rawTrade)))
                    {
                        continue;
                    }
                }
            }
            trades.append(ccxt.BaseExchange.FromTrade(trade));
            string tradeSymbol = trade.symbol;
            symbols[(string)tradeSymbol] = true;
        }
        List<object> keys = new List<object>(symbols.Keys);
        int keysLength = keys.Count;
        if ((keysLength == 0))
        {
            return;
        }
        client.resolve(trades, "myTrades");
        for (int i = 0; i < keys.Count; i++)
        {
            client.resolve(trades, ("myTrades::" + (keys[i])));
        }
    }

    /**
     * @method
     * @name interactivebrokers#watchBalance
     * @description watch balance and get the amount of funds available for trading or funds locked in orders, the cash comes from the account ledger stream, the first call takes a fetchBalance snapshot for the holdings and the locked amounts
     * @see https://www.interactivebrokers.com/docs/web-api/ws/account-ledger
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.accountId] the account id, defaults to options["accountId"]
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public async override Task<ccxt.Balances> WatchBalance(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        var accountIdqueryVariable = await this.loadAccountId(parameters);
        var accountId = ((IList<object>) accountIdqueryVariable)[0];
        var query = ((IList<object>) accountIdqueryVariable)[1];
        object url = await this.ibkrConnect();
        var client = this.client(url);
        string messageHash = "balance";
        string subscribeHash = ("sld::" + (accountId));
        if (!((client.subscriptions != null && client.subscriptions.ContainsKey(subscribeHash))))
        {
            IDictionary<string, object> options = this.safeDict(this.options, "watchBalance", new Dictionary<string, object>() {});
            bool? fetchBalanceSnapshot = this.safeBool(options, "fetchBalanceSnapshot", true);
            if ((fetchBalanceSnapshot == true))
            {
                Dictionary<string, object> snapshotRequest = new Dictionary<string, object>() {
                    { "accountId", accountId },
                };
                Dictionary<string, object> snapshot = ccxt.BaseExchange.FromBalances(await this.FetchBalance(this.extend(query, snapshotRequest)));
                // typed copy: the statically typed ports keep this.balance as a dictionary
                Dictionary<string, object> emptyBalance = new Dictionary<string, object>() {};
                this.balance = this.extend(emptyBalance, snapshot);
            }
        }
        // reusableFuture (), not watch () - the connection is already open (ibkrConnect), and go's watch () yields a channel
        var future = client.reusableFuture(messageHash);
        string emptyArgs = "{}"; // a separate literal, the php transpiler turns '+{}' into '+array()'
        await this.ibkrSubscribe(client, subscribeHash, ((("sld+" + (accountId)) + "+") + emptyArgs), new Dictionary<string, object>() {
            { "accountId", accountId },
        });
        object balance = await future;
        return ccxt.BaseExchange.ToBalances(balance);
    }

