    public virtual void handleBalance(WebSocketClient client, object message)
    {
        //
        //     {
        //         "result": [
        //             { "acctCode": "U1234567", "cashbalance": 2.0201311791131118E8, "key": "LedgerListBASE", "secondKey": "BASE", "settledCash": 2.02E8, "timestamp": 1700248325, ... },
        //             { "acctCode": "U1234567", "cashbalance": 1000.0, "key": "LedgerListUSD", "secondKey": "USD", "timestamp": 1700248325, ... },
        //             { "key": "LedgerListEUR", "timestamp": 1700248325 }
        //         ],
        //         "topic": "sld+U1234567"
        //     }
        //
        List<object> result = this.safeList(message, "result", new List<object>() {});
        bool changed = false;
        Int64? timestamp = null;
        for (int i = 0; i < result.Count; i++)
        {
            object entry = result[i];
            timestamp = this.safeTimestamp(entry, "timestamp", timestamp);
            string? cash = this.safeString(entry, "cashbalance");
            if ((cash == null))
            {
                continue;
            }
            string? key = this.safeString(entry, "key", "");
            string? currencyId = this.safeString(entry, "secondKey", key.Replace("LedgerList", (string)""));
            if (currencyId == "BASE")
            {
                continue;
            }
            string code = this.safeCurrencyCode(currencyId);
            IDictionary<string, object> account = this.safeDict(this.balance, code, this.account());
            account["total"] = cash;
            account["free"] = null; // recomputed from total - used
            this.balance[code] = account;
            changed = true;
        }
        if (!changed && ((this.balance != null && this.balance.ContainsKey("info"))))
        {
            return;
        }
        this.balance["info"] = message;
        this.balance["timestamp"] = timestamp;
        this.balance["datetime"] = this.iso8601(timestamp);
        this.balance = this.safeBalance(this.balance);
        client.resolve(this.balance, "balance");
    }

    public virtual void handleSessionStatus(WebSocketClient client, object message)
    {
        //
        //     { "topic": "sts", "args": { "authenticated": true, "competing": false, "message": "", "fail": "", "serverName": "...", "serverVersion": "..." } }
        //
        IDictionary<string, object> args = this.safeDict(message, "args", new Dictionary<string, object>() {});
        bool? authenticated = this.safeBool(args, "authenticated");
        if ((authenticated == null))
        {
            return;
        }
        if ((authenticated == true))
        {
            ((IDictionary<string,object>)client.subscriptions)["ibkrAuthenticated"] = true;
            client.resolve(true, "authenticated");
        } else
        {
            ((IDictionary<string,object>)client.subscriptions)["ibkrAuthenticated"] = false;
            if ((this.safeBool(this.options, "useGateway", false) == true))
            {
                // e.g. taken over by a login with the same username elsewhere, see options.autoRegainSession
                this.ibkrGatewayOnSessionLost();
            }
            var error = new AuthenticationError(((this.id + " the brokerage session is not authenticated ") + this.json(message)));
            client.reject(error);
        }
    }

    public virtual bool handleErrorMessage(WebSocketClient client, object message)
    {
        //
        //     { "topic": "smd+123", "error": "..." }
        //
        string? errorMessage = this.safeString(message, "error");
        if ((errorMessage == null))
        {
            return false;
        }
        string feedback = ((this.id + " ") + this.json(message));
        try
        {
            this.throwBroadlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("broad") ? this.exceptions["broad"] : null), errorMessage, feedback);
            throw new ExchangeError (feedback) ;
        } catch(Exception error)
        {
            client.reject(error);
        }
        return true;
    }

    public override object ping(WebSocketClient client)
    {
        // https://www.interactivebrokers.com/docs/web-api/ws/ping - "tic" keeps the websocket session alive, no response is sent
        return "tic";
    }

    public override void handleTextMessage(WebSocketClient client, object message)
    {
        // plain text frames carry no data, but like every message they prove the connection is alive
        client.lastPong = this.milliseconds();
    }

    public override void handleMessage(WebSocketClient client, object message)
    {
        //
        // every message (including the 10 second system heartbeats) proves the connection is alive
        //
        //     { "topic": "system", "success": "username" }
        //     { "topic": "system", "hb": 1702334859712 }
        //
        client.lastPong = this.milliseconds();
        if (this.handleErrorMessage(client, message))
        {
            return;
        }
        string? topic = this.safeString(message, "topic", "");
        if ((topic == "system") && !(this.safeBool(client.subscriptions, "ibkrConnected", false) == true))
        {
            ((IDictionary<string,object>)client.subscriptions)["ibkrConnected"] = true;
            client.resolve(true, "connected");
        }
        if (topic.StartsWith("smd+"))
        {
            this.handleTicker(client, message);
        } else if (topic.StartsWith("smh+"))
        {
            this.handleOHLCV(client, message);
        } else if (topic.StartsWith("sbd+"))
        {
            this.handleOrderBook(client, message);
        } else if (topic == "sor")
        {
            this.handleOrders(client, message);
        } else if (topic == "str")
        {
            this.handleMyTrades(client, message);
        } else if (topic.StartsWith("sld+"))
        {
            this.handleBalance(client, message);
        } else if (topic == "sts")
        {
            this.handleSessionStatus(client, message);
        }
    }
}
